script:
files = repo.list(".")
src = repo.read("src/cache.rs")
return {"files": files, "cache_rs": src[:3000]}

res2 = env.run(["find", ".", "-not", "-path", "./.git/*"], check=False)
res3 = env.run(["ls", "-la", "."], check=False)
return {"find": res2.stdout + res2.stderr, "ls": res3.stdout + res3.stderr}

repo.edit("src/cache.rs", "pub const CAPACITY: usize = 16;", "pub const CAPACITY: usize = 32;")
res = env.run(["cargo", "test"], check=False)
return {"file_after_edit": repo.read("src/cache.rs"), "code": res.code, "out": res.stdout, "err": res.stderr}
